import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <vector>

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int channels,
    int in_height,
    int in_width,
    int kernel_h,
    int kernel_w,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias,
    int out_height,
    int out_width)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * channels * out_height * out_width;

    if (idx < total) {
        int w_out = idx % out_width;
        int h_out = (idx / out_width) % out_height;
        int c     = (idx / (out_width * out_height)) % channels;
        int b     = idx / (out_width * out_height * channels);

        float sum_val = 0.0f;
        for (int kh = 0; kh < kernel_h; kh++) {
            for (int kw = 0; kw < kernel_w; kw++) {
                int in_h = h_out * stride_h - pad_h + kh * dilation_h;
                int in_w = w_out * stride_w - pad_w + kw * dilation_w;
                if (in_h >= 0 && in_h < in_height && in_w >= 0 && in_w < in_width) {
                    int in_idx = b * (channels * in_height * in_width)
                                 + c * (in_height * in_width)
                                 + in_h * in_width
                                 + in_w;
                    int wt_idx = c * (kernel_h * kernel_w)
                                 + kh * kernel_w
                                 + kw;
                    sum_val += input[in_idx] * weight[wt_idx];
                }
            }
        }
        if (has_bias) {
            sum_val += bias[c];
        }
        output[idx] = sum_val;
    }
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias)
{
    // input shape: B, C, H, W
    // weight shape: C, 1, kernel_h, kernel_w
    auto B = input.size(0);
    auto C = input.size(1);
    auto H = input.size(2);
    auto W = input.size(3);
    auto kernel_h = weight.size(2);
    auto kernel_w = weight.size(3);

    // compute output shape
    int out_height = (H + 2 * pad_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    int out_width  = (W + 2 * pad_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto options = torch::TensorOptions().device(input.device()).dtype(input.dtype());
    auto output = torch::zeros({B, C, out_height, out_width}, options);

    int total = B * C * out_height * out_width;
    const int block_size = 256;
    const int num_blocks = (total + block_size - 1) / block_size;

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        B, C, H, W,
        kernel_h, kernel_w,
        stride_h, stride_w,
        pad_h, pad_w,
        dilation_h, dilation_w,
        has_bias,
        out_height, out_width
    );

    return output;
}
""".strip()

depthwise_conv2d_cpp_source = r"""
torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h,
    int stride_w,
    int pad_h,
    int pad_w,
    int dilation_h,
    int dilation_w,
    bool has_bias);
""".strip()

depthwise_conv2d = load_inline(
    name="depthwise_conv2d",
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=["depthwise_conv2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Performs a custom depthwise 2D convolution using a custom CUDA kernel.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size_h: int,
        kernel_size_w: int,
        stride_h: int = 1,
        stride_w: int = 1,
        padding_h: int = 0,
        padding_w: int = 0,
        dilation_h: int = 1,
        dilation_w: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels  # for depthwise, out_channels usually == in_channels
        self.kernel_size_h = kernel_size_h
        self.kernel_size_w = kernel_size_w
        self.stride_h = stride_h
        self.stride_w = stride_w
        self.padding_h = padding_h
        self.padding_w = padding_w
        self.dilation_h = dilation_h
        self.dilation_w = dilation_w
        self.groups = groups
        self.has_bias = bias

        # Weight shape for depthwise: (in_channels, 1, kernel_size_h, kernel_size_w)
        self.weight = nn.Parameter(
            torch.randn(self.in_channels, 1, self.kernel_size_h, self.kernel_size_w)
        )
        if bias:
            self.bias = nn.Parameter(torch.zeros(self.in_channels))
        else:
            self.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return depthwise_conv2d.depthwise_conv2d_cuda(
            x,
            self.weight,
            self.bias if self.has_bias else torch.tensor([], device=x.device),
            self.stride_h,
            self.stride_w,
            self.padding_h,
            self.padding_w,
            self.dilation_h,
            self.dilation_w,
            self.has_bias
        )
